/**
 * Рендеринг даних у HTML
 */
function renderUserData(data, user) {
  // Оновлюємо ім'я користувача
  var usernameElement = document.querySelector('.header__username');
  var popupNameElement = document.querySelector('.header__user-info-name');
  var name = data.displayName || user.displayName || 'Learner';
  if (usernameElement) usernameElement.textContent = name;
  if (popupNameElement) popupNameElement.textContent = name;

  // Оновлюємо аватарки у хедері та в попапі
  if (user.photoURL) {
    var headerAvatar = document.querySelector('.header__username-avatar');
    var popupAvatar = document.querySelector('.header__user-info-img');
    if (headerAvatar) headerAvatar.src = user.photoURL;
    if (popupAvatar) popupAvatar.src = user.photoURL;
  }

  // Рендер списку мов (якщо збережені в Firestore)
  if (data.languages && Array.isArray(data.languages)) {
    renderLanguages(data.languages);
  }
}

/**
 * Генератор шаблону для мов
 */
function renderLanguages(languages) {
  var listContainer = document.querySelector('.your-languages__language-list');
  if (!listContainer) return;
  listContainer.innerHTML = languages.map(function (lang) {
    return "\n        <li class=\"your-languages__item\">\n            <a href=\"./languagepage.html?lang=".concat(lang.code, "\" class=\"your-languages__item-link\">\n                <img src=\"./src/img/country-flags-main/svg/").concat(lang.flag, ".svg\" alt=\"Flag\" class=\"your-languages__item-flag\">\n                <span class=\"your-languages__item-title\">").concat(lang.code.toUpperCase(), "</span>\n            </a>\n        </li>\n    ");
  }).join('');
}
